style.css:
@-moz-document domain("roblox.com") {
html, body, #container, #app-container {
        background: url("https://i.imgur.com/0RPNUYE.png") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Remove default dark mode background */
    body::before {
        content: none !important;
    }

    /* Fix the white background on some elements */
    .page-content, .content, .container-main, .container-lg, .container-md {
        background: transparent !important;
    }
}
